        for i, (a, b) in enumerate(rows):
            if any(r in three_rows for r in range(a, b)):
                hidden = i
                break
    else:
        for j, (a, b) in enumerate(cols):
            if any(c in three_cols for c in range(a, b)):
                hidden = j
                break

